import { useEffect, useState } from 'react'
import type { Target } from './types'

/** Groups of features, each with its own score (rule 4 of src/export_web.py). */
export type DimensionId = 'relieve' | 'temperatura' | 'superficie' | 'aridez'

export interface DimensionMeta {
  id: DimensionId
  features: string[]
  label: { es: string; en: string }
}

/** Data contract: docs/VISUALIZACION_COMPARACION.md. Generated by src/export_web.py. */
export interface FeatureMeta {
  id: string
  label: string
  unit: string
  dimension: DimensionId
  source_earth: string
  source_target: Partial<Record<Target, string>>
  default_weight: number
  /** Fixed physical axis [min, max] for drawing real values. */
  range?: [number, number]
}

export interface ComparisonTarget {
  id: string
  body: Target
  name: string
  lat?: number | null
  lng?: number | null
  /** Size of the area averaged around the site, e.g. "disk 10 km". */
  area?: string | null
  values: Record<string, number | null>
  /** Features switched off for this body: its value is outside anything found on Earth. */
  excluded?: string[]
  /** Best score of any Earth cell for this target. */
  best_score?: number | null
}

export interface ComparisonResult {
  target: string
  score: number | null
  /** Score of each dimension with the same formula; null = not comparable (e.g. Moon temperature). */
  dims?: Partial<Record<DimensionId, number | null>>
  sim: Record<string, number | null>
  best_match: string | null
  worst_match: string | null
  rank: number
  /** Share of sensitivity runs in which this cell stayed in the top N. */
  stability: number | null
}

/** Detailed 10 x 10 km characterization. Descriptive: not part of the score. */
export interface Characterization {
  source: string
  window_km: number
  status: string
  topography?: Record<string, number | string | null>
  environment?: Record<string, number | string | null>
  spectral?: Record<string, number | string | null>
  mineralogy?: { status: string; emit_granules: number }
  quality_flags?: string[]
}

export interface ComparisonSite {
  id: string
  /** catalog = site of web/src/data/sites.ts; discovery = best cell of a little-known region. */
  kind?: 'catalog' | 'discovery'
  /** Spanish name; discoveries also have name_en. Grid tiles are named after their country. */
  name: string
  name_en?: string
  country?: string
  country_en?: string
  /** A 2 x 2 degree tile of the worldwide search (the app shows its coordinates). */
  grid?: boolean
  lat: number
  lng: number
  /** Earth region of the database (data/regions_catalog.csv). */
  region?: string
  /** True when the region is a famous analog (kept as a control). */
  known?: boolean
  /** Why the region is in the database. */
  note?: string
  values: Record<string, number | null>
  results: ComparisonResult[]
  characterization?: Characterization
}

/** One map layer: the best Earth cells for one target, as [lat, lng, score]. */
export interface Heatmap {
  target: string
  cells: [number, number, number][]
}

export interface ComparisonData {
  version: string
  generated_at: string
  synthetic: boolean
  n_cells: number
  n_regions?: number
  stability_runs: number
  stability_top: number
  /** Minimum distance between the places of a ranked list (km). */
  spread_km?: number
  features: FeatureMeta[]
  dimensions?: DimensionMeta[]
  targets: ComparisonTarget[]
  sites: ComparisonSite[]
  /** Ranked lists per body: "general" (overall score) and one per comparable dimension. */
  rankings?: Partial<Record<Target, Partial<Record<RankingId, RankedPlace[]>>>>
}

export type RankingId = 'general' | DimensionId

/** One place of a ranked list: the site, its best Moon/Mars target and the score of that list. */
export interface RankedPlace {
  site: string
  target: string
  score: number
}

type LoadState = { status: 'loading' } | { status: 'error' } | { status: 'ready'; data: ComparisonData }

let cache: Promise<ComparisonData> | null = null

function load(): Promise<ComparisonData> {
  cache ??= fetch('/data/comparisons.json').then((r) => {
    if (!r.ok) throw new Error(`HTTP ${r.status}`)
    return r.json() as Promise<ComparisonData>
  })
  return cache
}

export function useComparisons(): LoadState {
  const [state, setState] = useState<LoadState>({ status: 'loading' })
  useEffect(() => {
    let alive = true
    load()
      .then((data) => alive && setState({ status: 'ready', data }))
      .catch(() => alive && setState({ status: 'error' }))
    return () => {
      alive = false
    }
  }, [])
  return state
}

/**
 * Same formula as src/compare.py (score_cells):
 *   sim_f = exp(-|d_f|)  =>  |d_f| = -ln(sim_f)
 *   score = exp(-sqrt(Σ w_f d_f² / Σ w_f))
 * so the score can be recomputed exactly in the browser for any weights.
 */
export function scoreWithWeights(sim: Record<string, number | null>, weights: Record<string, number>): number | null {
  let num = 0
  let den = 0
  for (const [feature, s] of Object.entries(sim)) {
    const w = weights[feature] ?? 0
    if (s == null || w <= 0) continue
    const d = -Math.log(Math.max(s, 1e-12))
    num += w * d * d
    den += w
  }
  if (den === 0) return null
  return Math.exp(-Math.sqrt(num / den))
}

/**
 * Exported Earth sites ranked for one target with the given weights.
 * Discoveries keep only the best place of each region, so one region
 * cannot fill the whole list; catalog sites are always kept.
 */
export function rankForTarget(data: ComparisonData, targetId: string, weights: Record<string, number>) {
  const ranked = data.sites
    .map((site) => {
      const result = site.results.find((r) => r.target === targetId)
      return result ? { site, result, score: scoreWithWeights(result.sim, weights) } : null
    })
    .filter((x): x is NonNullable<typeof x> => x !== null && x.score !== null)
    .sort((a, b) => (b.score ?? 0) - (a.score ?? 0))
  const seen = new Set<string>()
  return ranked.filter(({ site }) => {
    if (site.kind !== 'discovery' || !site.region) return true
    if (seen.has(site.region)) return false
    seen.add(site.region)
    return true
  })
}

const heatmapCache = new Map<string, Promise<Heatmap>>()

/** Map layer for one target (web/public/data/heatmap/<id>.json). */
export function loadHeatmap(targetId: string): Promise<Heatmap> {
  let p = heatmapCache.get(targetId)
  if (!p) {
    p = fetch(`/data/heatmap/${encodeURIComponent(targetId)}.json`).then((r) => {
      if (!r.ok) throw new Error(`HTTP ${r.status}`)
      return r.json() as Promise<Heatmap>
    })
    p.catch(() => heatmapCache.delete(targetId))
    heatmapCache.set(targetId, p)
  }
  return p
}
